const request = $input.first();
const query = request.json.query || {};
const binary = request.binary || {};
const cursoId = query.curso_id;
const institucionId = query.institucion_id;
if (!cursoId || !institucionId) throw new Error('curso_id e institucion_id son obligatorios.');
const files = Object.entries(binary);
if (!files.length) throw new Error('No se recibieron archivos PDF en multipart/form-data.');
return files.map(([key, file]) => {
  if (file.mimeType !== 'application/pdf' && !String(file.fileName || '').toLowerCase().endsWith('.pdf')) throw new Error(`El archivo ${file.fileName || key} no es PDF.`);
  return { json: { curso_id: Number(cursoId), institucion_id: String(institucionId), coordinador_id: query.coordinador_id ? String(query.coordinador_id) : null, namespace: `curso_${cursoId}`, archivo: file.fileName || key }, binary: { data: file } };
});

const sourceFiles = $('Normalizar PDFs del backend').all();
const outputs = $input.all();
const size = 1200;
const overlap = 150;
const chunks = [];
outputs.forEach((item, fileIndex) => {
  const source = sourceFiles[fileIndex]?.json;
  const text = String(item.json.data || '').replace(/\s+/g, ' ').trim();
  if (!source || !text) return;
  let chunkIndex = 0;
  for (let start = 0; start < text.length; start += size - overlap) {
    const texto = text.slice(start, start + size).trim();
    if (texto.length < 30) continue;
    const safeFile = source.archivo.replace(/[^a-zA-Z0-9_-]/g, '_');
    chunks.push({ json: { ...source, texto, pagina: null, chunk_index: chunkIndex, vector_id: `curso_${source.curso_id}__${safeFile}__c${chunkIndex}` } });
    chunkIndex += 1;
    if (start + size >= text.length) break;
  }
});
if (!chunks.length) throw new Error('No se extrajo texto utilizable de los PDF recibidos.');
return chunks;

