if (!vectors.length) throw new Error('OpenAI no devolvió embeddings válidos.');
return [{ json: { namespace: request.chunks[0].namespace, vectors, chunks_indexados: vectors.length, archivos_procesados: new Set(request.chunks.map((chunk) => chunk.archivo)).size } }];
